import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.DYPTBNgj.js";const g=JSON.parse('{"title":"Configure the daemon","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788977791000}'),n={name:"guide/configuration.md"};function o(d,e,r,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="configure-the-daemon" tabindex="-1">Configure the daemon <a class="header-anchor" href="#configure-the-daemon" aria-label="Permalink to &quot;Configure the daemon&quot;">​</a></h1><p>Boomerangz keeps host-wide settings in TOML and dataset-specific policy in ZFS properties. This separation lets a dataset carry its own snapshot and replication policy while connection details and credentials remain on the host.</p><h2 id="configuration-files" tabindex="-1">Configuration files <a class="header-anchor" href="#configuration-files" aria-label="Permalink to &quot;Configuration files&quot;">​</a></h2><p>The primary file is <code>/etc/boomerangz/config.toml</code>. Files ending in <code>.toml</code> in <code>/etc/boomerangz/config.d</code> are applied afterward in filename order.</p><p>Later scalar values override earlier values, tables merge, and arrays replace earlier arrays. Unknown fields are errors.</p><p>Start with only the settings you need:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">daemon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reconcile_interval = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1m&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">inactive_grace_period = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;24h&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">credentials_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/boomerangz/credentials.d&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">identity_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/var/lib/boomerangz/identity&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socket_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/run/boomerangz/boomerangz.sock&quot;</span></span></code></pre></div><h2 id="validate-changes" tabindex="-1">Validate changes <a class="header-anchor" href="#validate-changes" aria-label="Permalink to &quot;Validate changes&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span></span></code></pre></div><p><code>config check</code> validates the primary file, all drop-ins, and the merged result. <code>config show</code> displays the effective configuration with private-key fields redacted.</p><p>Apply the files to the running daemon without interrupting active work:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-j59Ua" id="tab-VAWor58" checked><label data-title="Linux / systemd" for="tab-VAWor58">Linux / systemd</label><input type="radio" name="group-j59Ua" id="tab-phtnEgV"><label data-title="Direct command" for="tab-phtnEgV">Direct command</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz.service</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div></div></div><p>Reload reads and validates the same primary file and drop-ins that started the daemon. If validation or preparation fails, the running configuration remains unchanged and <code>systemctl reload</code> fails. The direct command prints a JSON result containing the new configuration <code>generation</code>, the fields <code>applied</code> live, and any <code>restart_required</code> fields. The service action records that result in the system journal; inspect it with <code>journalctl -u boomerangz.service</code>. Check <code>restart_required</code> before considering the change complete.</p><p>Most settings, including worker counts, remotes, listeners, credential and socket paths, and restricted-shell roots, are applied live. Running jobs finish with the configuration they captured when they started. Changing <code>paths.identity_dir</code> requires a restart and is retained at its previous value until then because it changes the installation&#39;s identity and authorization boundary.</p><p>The packaged systemd service runs the reload command as the <code>boomerangz</code> user. By default, the direct <code>config reload</code> command connects to <code>/run/boomerangz/boomerangz.sock</code>. Use <code>--socket PATH</code> when the running daemon&#39;s current control socket is elsewhere. If the reload changes <code>socket_path</code>, use the new path for later control commands and update the service&#39;s <code>ExecReload</code> override so future <code>systemctl reload</code> operations select it.</p><h2 id="scheduling-and-concurrency" tabindex="-1">Scheduling and concurrency <a class="header-anchor" href="#scheduling-and-concurrency" aria-label="Permalink to &quot;Scheduling and concurrency&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it controls</th></tr></thead><tbody><tr><td><code>reconcile_interval</code></td><td><code>1m</code></td><td>How often the daemon discovers new or changed dataset policy. This is not the snapshot interval.</td></tr><tr><td><code>inactive_grace_period</code></td><td><code>24h</code></td><td>How long an inactive owned dataset remains recoverable before automatic retirement. <code>0s</code> disables automatic retirement.</td></tr><tr><td><code>management_workers</code></td><td><code>0</code></td><td>Concurrent short management tasks. Zero uses the logical CPU count available to the process.</td></tr><tr><td><code>local_transfer_workers</code></td><td><code>2</code></td><td>Concurrent transfers between datasets on this host.</td></tr><tr><td><code>remote_transfer_workers</code></td><td><code>1</code></td><td>Concurrent network transfers across all remote destinations.</td></tr></tbody></table><p>Worker counts limit concurrency, not bandwidth. Increase them only after observing storage and network load.</p><h2 id="paths" tabindex="-1">Paths <a class="header-anchor" href="#paths" aria-label="Permalink to &quot;Paths&quot;">​</a></h2><p>All configured paths must be absolute. Keep the defaults unless your host has a clear reason to relocate them.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>credentials_dir</code></td><td><code>/etc/boomerangz/credentials.d</code></td><td>Imported pairings and dedicated SSH credentials.</td></tr><tr><td><code>identity_dir</code></td><td><code>/var/lib/boomerangz/identity</code></td><td>Installation identity and managed certificate material. Preserve it for the life of this installation.</td></tr><tr><td><code>socket_path</code></td><td><code>/run/boomerangz/boomerangz.sock</code></td><td>Local status and control socket.</td></tr></tbody></table><p>For the complete schema, see the <a href="/reference/configuration">configuration reference</a>.</p>`,22)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
